const ws=await figma.getNodeByIdAsync('3:2');await figma.setCurrentPageAsync(ws);
const o=[];
for(const f of ws.children){if(!/^\d\d_/.test(f.name))continue;
 const bad=[];for(const c of f.children){if(c.x+c.width>402.5||c.y+c.height>874.5||c.x<-0.5)bad.push(c.name+` ${Math.round(c.x)},${Math.round(c.y)} ${Math.round(c.width)}x${Math.round(c.height)}`)}
 o.push(f.name+' '+f.children.length+' n; reactions:'+f.findAll(n=>n.reactions&&n.reactions.length).length+' off:'+bad.join(' | '))}
